//! Chimes, played natively so they sound on time even when the webview is throttled.
//! The WAV files are generated by scripts/make-sounds.mjs (CC0, see THIRD_PARTY_LICENSES.md).

use std::io::Cursor;

const BOWL: &[u8] = include_bytes!("../../public/sounds/bowl.wav");
const QIN: &[u8] = include_bytes!("../../public/sounds/qin.wav");
const BELL: &[u8] = include_bytes!("../../public/sounds/bell.wav");

fn bytes_for(name: &str) -> &'static [u8] {
    match name {
        "qin" => QIN,
        "bell" => BELL,
        _ => BOWL,
    }
}

/// Play a chime on a short-lived audio thread. Failures (no audio device) are logged.
pub fn play(name: &str, volume: f32) {
    let bytes = bytes_for(name);
    let volume = volume.clamp(0.0, 1.0);
    std::thread::spawn(move || {
        let result = (|| -> Result<(), Box<dyn std::error::Error>> {
            let (_stream, handle) = rodio::OutputStream::try_default()?;
            let sink = rodio::Sink::try_new(&handle)?;
            sink.set_volume(volume);
            sink.append(rodio::Decoder::new(Cursor::new(bytes))?);
            sink.sleep_until_end();
            Ok(())
        })();
        if let Err(err) = result {
            eprintln!("shanshui: could not play sound: {err}");
        }
    });
}
